import React, { useMemo, useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import {
  ChevronRight,
  Coffee,
  Croissant,
  CupSoda,
  Heart,
  LayoutGrid,
  Minus,
  Package,
  Plus,
  Search,
  Settings2,
  ShoppingCart,
  Store,
  User,
  X
} from "lucide-react";
import { useAuth } from "./AuthContext";
import { useCart } from "./CartContext";
import { useTheme } from "./ThemeContext";
import { apiFetch } from "./api";
import { CATEGORIES, FILTERS, PRODUCTS } from "./catalog";
import { BUYER_ORDERS } from "./vendorMock";
import { h, f } from "./h";
import {
  Badge,
  Button,
  Field,
  GlassCard,
  GlassPanel,
  LogoMark,
  RefImage,
  TextInput,
  ThemeToggleButton
} from "./ui";

function BuyerHeader({ onOpenCart, title }) {
  const { dark, toggle } = useTheme();
  const { user, accessToken } = useAuth();
  const { count } = useCart();
  const nav = useNavigate();
  const [q, setQ] = useState("");

  return h(
    "header",
    {
      className:
        "sticky top-0 z-40 border-b border-white/10 bg-white/30 shadow-sm backdrop-blur-xl dark:bg-night-900/40"
    },
    h("div", { className: "mx-auto flex max-w-7xl flex-col gap-3 px-4 py-3 sm:flex-row sm:items-center sm:justify-between sm:gap-4 sm:px-6" }, [
      h("div", { className: "flex items-center justify-between gap-3 sm:justify-start" }, [
        h(Link, { to: "/shop", className: "flex items-center gap-2" }, [
          h(LogoMark, { className: "h-9 w-9" }),
          h("div", { className: "leading-tight" }, [
            h("span", { className: "font-display text-lg font-bold text-slate-900 dark:text-white" }, "BrewMart"),
            title &&
              h("span", { className: "ml-2 rounded-full bg-sky-500/15 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-sky-700 dark:text-sky-300" }, title)
          ])
        ]),
        h("div", { className: "flex items-center gap-2 sm:hidden" }, [
          h(ThemeToggleButton, { dark, onToggle: toggle }),
          h(
            Button,
            {
              variant: "ghost",
              className: "!min-h-[44px] !px-3",
              onClick: () => nav("/vendor/dashboard")
            },
            "Vendor"
          )
        ])
      ]),
      h("div", { className: "flex flex-1 items-center gap-2" }, [
        h("div", { className: "relative flex flex-1 items-center" }, [
          h(Search, {
            className: "pointer-events-none absolute left-3 h-4 w-4 text-slate-400"
          }),
          h(TextInput, {
            value: q,
            onChange: (e) => setQ(e.target.value),
            placeholder: "Search products, brands…",
            className: "!rounded-full !pl-10 !pr-24"
          }),
          h(
            Button,
            {
              variant: "primary",
              className: "!absolute right-1 top-1/2 !min-h-[36px] -translate-y-1/2 !rounded-full !px-4 !py-2 !text-sm",
              type: "button",
              onClick: () => {}
            },
            "Search"
          )
        ])
      ]),
      h(
        "div",
        { className: "flex items-center justify-center gap-1 border-t border-white/10 pt-2 sm:hidden" },
        [
          h(
            Link,
            {
              to: "/orders",
              className:
                "tap-target flex flex-1 items-center justify-center gap-1 rounded-xl py-2 text-xs font-medium text-slate-700 dark:text-slate-200"
            },
            [h(Package, { className: "h-4 w-4" }), "Orders"]
          ),
          h(
            Link,
            {
              to: "/profile",
              className:
                "tap-target flex flex-1 items-center justify-center gap-1 rounded-xl py-2 text-xs font-medium text-slate-700 dark:text-slate-200"
            },
            [h(User, { className: "h-4 w-4" }), "Profile"]
          ),
          h(
            Button,
            {
              variant: "ghost",
              className: "flex-1 !min-h-[40px] !rounded-xl !py-2 !text-xs",
              type: "button",
              onClick: onOpenCart
            },
            [h(ShoppingCart, { className: "h-4 w-4" }), "Cart"]
          )
        ]
      ),
      h("div", { className: "hidden items-center gap-2 sm:flex" }, [
        h(ThemeToggleButton, { dark, onToggle: toggle }),
        h(
          Link,
          {
            to: "/orders",
            className:
              "tap-target inline-flex items-center gap-1 rounded-2xl px-3 text-sm font-medium text-slate-700 hover:bg-white/40 dark:text-slate-200 dark:hover:bg-white/10"
          },
          [h(Package, { className: "h-4 w-4" }), h("span", { className: "hidden lg:inline" }, "Orders")]
        ),
        h(
          Link,
          {
            to: "/profile",
            className:
              "tap-target inline-flex items-center gap-1 rounded-2xl px-3 text-sm font-medium text-slate-700 hover:bg-white/40 dark:text-slate-200 dark:hover:bg-white/10"
          },
          [h(User, { className: "h-4 w-4" }), h("span", { className: "hidden lg:inline" }, "Profile")]
        ),
        h(
          Button,
          {
            variant: "ghost",
            className: "relative !min-h-[44px]",
            type: "button",
            onClick: onOpenCart
          },
          [
            h(ShoppingCart, { className: "h-5 w-5" }),
            h("span", { className: "hidden sm:inline" }, "Cart"),
            count > 0 &&
              h(
                "span",
                {
                  className:
                    "absolute -right-1 -top-1 flex h-5 min-w-[1.25rem] items-center justify-center rounded-full bg-sky-500 px-1 text-[10px] font-bold text-white"
                },
                String(count)
              )
          ]
        ),
        accessToken && user?.role === "seller"
          ? h(
              Link,
              { to: "/vendor/dashboard" },
              h(
                Button,
                { variant: "primary", className: "!min-h-[44px] !rounded-full !px-4 !text-sm sm:!px-5" },
                "Vendor view"
              )
            )
          : h(
              Link,
              { to: user ? "/vendor/dashboard" : "/login" },
              h(
                Button,
                { variant: "primary", className: "!min-h-[44px] !rounded-full !px-4 !text-sm sm:!px-5" },
                "Vendor view"
              )
            )
      ])
    ])
  );
}

function CategoryRow({ active, onSelect }) {
  const icons = {
    all: Store,
    coffee: Coffee,
    beans: Package,
    gear: Settings2,
    snacks: Croissant,
    mugs: CupSoda
  };
  return h(
    "div",
    { className: "no-scrollbar -mx-4 flex gap-3 overflow-x-auto px-4 pb-2 sm:mx-0 sm:flex-wrap sm:overflow-visible sm:px-0" },
    CATEGORIES.map((c) => {
      const Icon = icons[c.id] || LayoutGrid;
      const isOn = active === c.id;
      return h(
        "button",
        {
          key: c.id,
          type: "button",
          onClick: () => onSelect(c.id),
          className: `flex min-w-[4.5rem] flex-col items-center gap-1 rounded-2xl border px-3 py-2 text-xs font-medium transition sm:min-w-0 sm:flex-row sm:gap-2 sm:px-4 sm:text-sm ${
            isOn
              ? "border-sky-500/50 bg-sky-500/15 text-slate-900 dark:border-sky-400/40 dark:text-white"
              : "border-transparent bg-white/30 text-slate-700 hover:bg-white/50 dark:bg-white/5 dark:text-slate-200 dark:hover:bg-white/10"
          }`
        },
        [
          h(
            "span",
            {
              className: `flex h-10 w-10 items-center justify-center rounded-full sm:h-9 sm:w-9 ${
                isOn ? "bg-sky-600 text-white" : "bg-slate-200/80 text-slate-700 dark:bg-night-800 dark:text-slate-200"
              }`
            },
            h(Icon, { className: "h-5 w-5" })
          ),
          c.label
        ]
      );
    })
  );
}

export function CartDrawer({ open, onClose }) {
  const { items, subtotal, setQty, remove, clear } = useCart();
  const { accessToken } = useAuth();
  const [loading, setLoading] = useState(false);
  const [err, setErr] = useState("");

  const checkout = async () => {
    setErr("");
    if (!accessToken) {
      window.location.assign("/login");
      return;
    }
    if (subtotal <= 0) return;
    setLoading(true);
    try {
      const data = await apiFetch("/api/payments/create-checkout-session", {
        method: "POST",
        headers: { Authorization: `Bearer ${accessToken}` },
        json: { amount: Number(subtotal.toFixed(2)), currency: "usd" }
      });
      if (data.url) {
        clear();
        window.location.href = data.url;
      } else {
        setErr("Checkout session missing redirect URL. Is Stripe configured?");
      }
    } catch (ex) {
      setErr(ex.message || "Checkout failed");
    } finally {
      setLoading(false);
    }
  };

  if (!open) return null;
  return h(
    "div",
    { className: "fixed inset-0 z-50 flex justify-end" },
    [
      h("button", {
        type: "button",
        className: "absolute inset-0 bg-slate-950/60 backdrop-blur-sm",
        onClick: onClose,
        "aria-label": "Close cart overlay"
      }),
      h(
        GlassPanel,
        {
          className: "relative z-10 m-0 h-full w-full max-w-md rounded-none border-l border-white/10 sm:m-4 sm:h-[calc(100%-2rem)] sm:rounded-3xl",
          onClick: (e) => e.stopPropagation()
        },
        [
          h("div", { className: "flex items-center justify-between border-b border-white/10 pb-4" }, [
            h("div", { className: "flex items-center gap-2" }, [
              h(ShoppingCart, { className: "h-5 w-5 text-sky-400" }),
              h("h2", { className: "text-lg font-semibold text-slate-900 dark:text-white" }, "Your cart")
            ]),
            h(
              "button",
              {
                type: "button",
                className: "tap-target rounded-2xl p-2 hover:bg-white/10",
                onClick: onClose
              },
              h(X, { className: "h-5 w-5" })
            )
          ]),
          h("div", { className: "mt-4 flex max-h-[55vh] flex-col gap-3 overflow-y-auto pr-1" }, [
            items.length === 0 &&
              h("p", { className: "text-sm text-slate-500 dark:text-slate-400" }, "Your cart is empty."),
            items.map((p) =>
              h(GlassCard, { key: p.id, className: "!p-3" }, [
                h("div", { className: "flex gap-3" }, [
                  h(RefImage, {
                    n: p.imageRef,
                    alt: p.name,
                    className: "h-16 w-16 shrink-0 rounded-xl"
                  }),
                  h("div", { className: "min-w-0 flex-1" }, [
                    h("p", { className: "truncate font-semibold text-slate-900 dark:text-white" }, p.name),
                    h("p", { className: "text-xs text-slate-500 dark:text-slate-400" }, p.blurb),
                    h("p", { className: "mt-1 text-sm font-bold text-sky-600 dark:text-sky-300" }, `$${p.price.toFixed(2)}`),
                    h("div", { className: "mt-2 flex items-center gap-2" }, [
                      h(
                        "button",
                        {
                          type: "button",
                          className: "tap-target rounded-xl border border-white/15 p-2 hover:bg-white/10",
                          onClick: () => setQty(p.id, p.qty - 1)
                        },
                        h(Minus, { className: "h-4 w-4" })
                      ),
                      h("span", { className: "w-6 text-center text-sm font-semibold" }, String(p.qty)),
                      h(
                        "button",
                        {
                          type: "button",
                          className: "tap-target rounded-xl border border-white/15 p-2 hover:bg-white/10",
                          onClick: () => setQty(p.id, p.qty + 1)
                        },
                        h(Plus, { className: "h-4 w-4" })
                      ),
                      h(
                        "button",
                        {
                          type: "button",
                          className: "ml-auto text-xs font-semibold text-rose-400 hover:underline",
                          onClick: () => remove(p.id)
                        },
                        "Remove"
                      )
                    ])
                  ])
                ])
              ])
            )
          ]),
          err && h("p", { className: "mt-3 text-sm text-rose-400" }, err),
          h("div", { className: "mt-6 space-y-2 border-t border-white/10 pt-4 text-sm" }, [
            h("div", { className: "flex justify-between text-slate-600 dark:text-slate-400" }, [
              h("span", null, "Subtotal"),
              h("span", { className: "font-semibold text-slate-900 dark:text-white" }, `$${subtotal.toFixed(2)}`)
            ]),
            h("div", { className: "flex justify-between text-slate-600 dark:text-slate-400" }, [
              h("span", null, "Delivery"),
              h("span", { className: "font-semibold text-emerald-400" }, "Free")
            ]),
            h("div", { className: "flex justify-between text-lg font-bold text-slate-900 dark:text-white" }, [
              h("span", null, "Total"),
              h("span", null, `$${subtotal.toFixed(2)}`)
            ]),
            h(
              Button,
              {
                className: "mt-3 w-full !rounded-2xl",
                onClick: checkout,
                loading,
                disabled: items.length === 0
              },
              ["Proceed to checkout ", h(ChevronRight, { className: "h-4 w-4" })]
            )
          ])
        ]
      )
    ]
  );
}

export function ShopPage() {
  const [cat, setCat] = useState("all");
  const [fil, setFil] = useState("all");
  const [cartOpen, setCartOpen] = useState(false);
  const { add } = useCart();

  const filtered = useMemo(() => {
    return PRODUCTS.filter((p) => {
      if (cat !== "all" && p.category !== cat) return false;
      if (fil === "all") return true;
      return p.filter.includes(fil);
    });
  }, [cat, fil]);

  return h("div", { className: "min-h-screen pb-24" }, [
    h(BuyerHeader, { onOpenCart: () => setCartOpen(true) }),
    h("div", { className: "relative mx-auto max-w-7xl px-4 py-6 sm:px-6" }, [
      h(RefImage, {
        n: 4,
        alt: "",
        className: "pointer-events-none absolute left-1/2 top-0 -z-10 h-64 w-full max-w-3xl -translate-x-1/2 rounded-[2rem] object-cover opacity-25 blur-2xl dark:opacity-20"
      }),
      h("section", { className: "mb-8" }, h(CategoryRow, { active: cat, onSelect: setCat })),
      h(
        GlassCard,
        { className: "relative mb-10 overflow-hidden !border-sky-500/20 !bg-gradient-to-br !from-sky-900/90 !to-night-950 !p-0 !shadow-2xl" },
        h("div", { className: "grid gap-6 p-6 sm:grid-cols-2 sm:items-center sm:p-10" }, [
          h("div", { className: "space-y-4" }, [
            h(
              "h1",
              { className: "font-display text-3xl font-bold leading-tight text-white sm:text-4xl" },
              "Discover premium coffee & more"
            ),
            h(
              "p",
              { className: "max-w-md text-sm text-white/85 sm:text-base" },
              "Handpicked products from artisan vendors around the world."
            ),
            h("div", { className: "flex flex-wrap gap-3" }, [
              h(
                Button,
                {
                  variant: "ghost",
                  className: "!border-white/40 !bg-white/90 !text-slate-900 hover:!bg-white"
                },
                "Shop now"
              ),
              h(
                Button,
                {
                  variant: "ghost",
                  className: "!border-white/50 !bg-transparent !text-white hover:!bg-white/10"
                },
                "Browse categories"
              )
            ])
          ]),
          h("div", { className: "relative hidden sm:block" }, h(RefImage, { n: 11, alt: "Hero", className: "h-56 w-full rounded-3xl object-cover opacity-90" }))
        ])
      ),
      h("div", { className: "mb-4 flex flex-wrap items-center gap-2" }, [
        h("span", { className: "text-sm font-semibold text-slate-600 dark:text-slate-300" }, "Filter:"),
        FILTERS.map((fitem) =>
          h(
            "button",
            {
              key: fitem.id,
              type: "button",
              onClick: () => setFil(fitem.id),
              className: `tap-target rounded-full px-4 py-2 text-sm font-medium transition ${
                fil === fitem.id
                  ? "bg-sky-600 text-white shadow-lg shadow-sky-900/30"
                  : "glass text-slate-700 hover:bg-white/50 dark:text-slate-200 dark:hover:bg-white/10"
              }`
            },
            fitem.label
          )
        )
      ]),
      h("h2", { className: "mb-4 font-display text-xl font-bold text-slate-900 dark:text-white sm:text-2xl" }, "Featured products"),
      h(
        "div",
        { className: "grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4" },
        filtered.map((p) =>
          h(GlassCard, { key: p.id, className: "flex flex-col !p-4" }, [
            h("div", { className: "relative" }, [
              p.badge &&
                h(
                  "span",
                  {
                    className: "absolute left-2 top-2 rounded-full bg-amber-500/90 px-2 py-0.5 text-[10px] font-bold uppercase text-slate-900"
                  },
                  p.badge
                ),
              h(RefImage, { n: p.imageRef, alt: p.name, className: "h-40 w-full rounded-2xl object-cover sm:h-44" })
            ]),
            h("div", { className: "mt-3 flex items-start justify-between gap-2" }, [
              h("div", { className: "min-w-0" }, [
                h("h3", { className: "truncate font-semibold text-slate-900 dark:text-white" }, p.name),
                h("p", { className: "text-xs capitalize text-slate-500 dark:text-slate-400" }, p.category)
              ]),
              h(
                "button",
                {
                  type: "button",
                  className: "tap-target rounded-xl p-2 text-slate-400 hover:bg-white/10 hover:text-rose-400",
                  "aria-label": "Wishlist"
                },
                h(Heart, { className: "h-5 w-5" })
              )
            ]),
            h("div", { className: "mt-2 flex items-center justify-between" }, [
              h("span", { className: "text-lg font-bold text-sky-600 dark:text-sky-300" }, `$${p.price.toFixed(2)}`)
            ]),
            h(
              Button,
              {
                variant: "ghost",
                className: "mt-3 w-full !justify-center !rounded-2xl border-sky-500/30",
                type: "button",
                onClick: () => add(p, 1)
              },
              [h(ShoppingCart, { className: "h-4 w-4" }), "Add to cart"]
            )
          ])
        )
      )
    ]),
    h(CartDrawer, { open: cartOpen, onClose: () => setCartOpen(false) }),
    h(
      "button",
      {
        type: "button",
        className:
          "fixed bottom-4 right-4 z-30 flex items-center gap-2 rounded-full bg-gradient-to-r from-sky-500 to-blue-600 px-5 py-3 text-sm font-semibold text-white shadow-xl shadow-sky-900/40 sm:hidden",
        onClick: () => setCartOpen(true)
      },
      [h(ShoppingCart, { className: "h-5 w-5" }), "Cart"]
    )
  ]);
}

export function OrdersPage() {
  const [cartOpen, setCartOpen] = useState(false);
  const statusTone = (s) => {
    if (s === "Delivered") return "success";
    if (s === "In Transit") return "warn";
    return "neutral";
  };
  return h("div", { className: "min-h-screen" }, [
    h(BuyerHeader, { onOpenCart: () => setCartOpen(true), title: "Shop" }),
    h("div", { className: "mx-auto max-w-4xl px-4 py-8 sm:px-6" }, [
      h("div", { className: "mb-6 flex flex-wrap items-center justify-between gap-3" }, [
        h("h1", { className: "flex items-center gap-2 font-display text-2xl font-bold text-slate-900 dark:text-white" }, [
          h(Package, { className: "h-7 w-7 text-sky-400" }),
          "My orders"
        ]),
        h(
          Link,
          { to: "/shop" },
          h(Button, { variant: "ghost", className: "!rounded-full" }, "Shop more")
        )
      ]),
      h("div", { className: "space-y-4" }, [
        BUYER_ORDERS.map((o) =>
          h(GlassCard, { key: o.id, className: "flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between" }, [
            h("div", { className: "flex gap-3" }, [
              h(RefImage, { n: o.imageRef, alt: o.name, className: "h-14 w-14 rounded-xl object-cover" }),
              h("div", {}, [
                h("p", { className: "font-semibold text-slate-900 dark:text-white" }, o.name),
                h("p", { className: "text-sm text-slate-500 dark:text-slate-400" }, `Ordered ${o.date} · $${o.price.toFixed(2)}`)
              ])
            ]),
            h(Badge, { tone: statusTone(o.status) }, o.status)
          ])
        )
      ])
    ]),
    h(CartDrawer, { open: cartOpen, onClose: () => setCartOpen(false) })
  ]);
}

export function ProfilePage() {
  const [cartOpen, setCartOpen] = useState(false);
  const { user, accessToken } = useAuth();
  const [name, setName] = useState("");
  const [email, setEmail] = useState(user?.email || "");
  const [phone, setPhone] = useState("+233 24 000 0000");

  return h("div", { className: "min-h-screen" }, [
    h(BuyerHeader, { onOpenCart: () => setCartOpen(true) }),
    h("div", { className: "mx-auto max-w-3xl px-4 py-10 sm:px-6" }, [
      h("div", { className: "mb-8 flex flex-col items-center text-center" }, [
        h(RefImage, { n: 12, alt: "Profile", className: "h-24 w-24 rounded-full object-cover ring-4 ring-sky-500/30" }),
        h("h1", { className: "mt-4 font-display text-2xl font-bold text-slate-900 dark:text-white" }, name || user?.email || "Your profile"),
        h("p", { className: "text-sm text-slate-500 dark:text-slate-400" }, user?.email || "Sign in to sync your account")
      ]),
      h(GlassPanel, { className: "mb-6" }, [
        h("h2", { className: "text-lg font-semibold text-slate-900 dark:text-white" }, "Account details"),
        h("div", { className: "mt-4 space-y-4" }, [
          h(Field, { label: "Full name" }, h(TextInput, { value: name, onChange: (e) => setName(e.target.value), placeholder: "Akosuah Mensah" })),
          h(Field, { label: "Email" }, h(TextInput, { type: "email", value: email, onChange: (e) => setEmail(e.target.value), disabled: !!user?.email })),
          h(Field, { label: "Phone" }, h(TextInput, { value: phone, onChange: (e) => setPhone(e.target.value) })),
          h(
            Button,
            {
              variant: "primary",
              className: "w-full sm:w-auto",
              type: "button",
              onClick: () => {}
            },
            "Save changes"
          ),
          !accessToken &&
            h("p", { className: "text-sm text-amber-400" }, "You are browsing as a guest. Log in to persist profile changes.")
        ])
      ]),
      h(GlassCard, {}, h("div", { className: "grid grid-cols-3 gap-4 text-center" }, [
        h("div", {}, [
          h("p", { className: "text-2xl font-bold text-slate-900 dark:text-white" }, "12"),
          h("p", { className: "text-xs text-slate-500 dark:text-slate-400" }, "Orders")
        ]),
        h("div", {}, [
          h("p", { className: "text-2xl font-bold text-slate-900 dark:text-white" }, "5"),
          h("p", { className: "text-xs text-slate-500 dark:text-slate-400" }, "Wishlist")
        ]),
        h("div", {}, [
          h("p", { className: "text-2xl font-bold text-slate-900 dark:text-white" }, "$248"),
          h("p", { className: "text-xs text-slate-500 dark:text-slate-400" }, "Spent")
        ])
      ]))
    ]),
    h(CartDrawer, { open: cartOpen, onClose: () => setCartOpen(false) })
  ]);
}

